<?= $this->extend('admin/layouts/main') ?><?= $this->section('content') ?><h1 class="h3"><?= esc($title) ?></h1><form method="post" enctype="multipart/form-data" action="<?= $row?site_url('admin/guides/'.$row['id']):site_url('admin/guides') ?>" class="card p-4"><input type="hidden" name="_method" value="<?= $row?'PUT':'POST' ?>"><?= csrf_field() ?><div class="row g-3"><div class="col-md-8"><label class="form-label">Title<input class="form-control" name="title" maxlength="190" value="<?= esc(old('title',$row['title']??''),'attr') ?>" required></label></div><div class="col-md-4"><label class="form-label">Slug<input class="form-control" name="slug" value="<?= esc(old('slug',$row['slug']??''),'attr') ?>"></label></div><div class="col-md-6"><label class="form-label">Category<select class="form-select" name="category_id"><option value="">None</option><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= (int)old('category_id',$row['category_id']??0)===(int)$c['id']?'selected':'' ?>><?= esc($c['name']) ?></option><?php endforeach ?></select></label></div><div class="col-md-3"><label class="form-label">Status<select class="form-select" name="status"><?php foreach(['draft','published','scheduled'] as $s): ?><option value="<?= $s ?>" <?= old('status',$row['status']??'draft')===$s?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach ?></select></label></div><div class="col-md-3"><label class="form-label">Publish date<input class="form-control" type="datetime-local" name="published_at" value="<?= esc(old('published_at',!empty($row['published_at'])?date('Y-m-d\TH:i',strtotime($row['published_at'])):''),'attr') ?>"></label></div><div class="col-12"><label class="form-label w-100">Excerpt<textarea class="form-control" name="excerpt" rows="2"><?= esc(old('excerpt',$row['excerpt']??'')) ?></textarea></label></div><div class="col-12"><label class="form-label w-100">Content<textarea class="form-control" id="guide-editor" name="content" rows="16" required><?= esc(old('content',$row['content']??'')) ?></textarea></label><small>Use headings H2/H3 for the table of contents.</small></div><div class="col-md-6"><label class="form-label">Featured image<input class="form-control" type="file" name="featured_image" accept="image/jpeg,image/png,image/webp"></label></div><div class="col-md-6"><label class="form-check mt-4"><input class="form-check-input" type="checkbox" name="featured" value="1" <?= old('featured',$row['featured']??0)?'checked':'' ?>> Featured</label></div><div class="col-md-6"><label class="form-label">SEO title<input class="form-control" name="seo_title" maxlength="190" value="<?= esc(old('seo_title',$row['seo_title']??''),'attr') ?>"></label></div><div class="col-md-6"><label class="form-label w-100">SEO description<textarea class="form-control" name="seo_description"><?= esc(old('seo_description',$row['seo_description']??'')) ?></textarea></label></div><div class="col-md-6"><label class="form-label w-100">Related products<select class="form-select" name="product_id[]" multiple size="8"><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>" <?= in_array($p['id'],$productIds)?'selected':'' ?>><?= esc($p['name']) ?></option><?php endforeach ?></select></label></div><div class="col-md-6"><label class="form-label w-100">Related packages<select class="form-select" name="package_id[]" multiple size="8"><?php foreach($packages as $p): ?><option value="<?= $p['id'] ?>" <?= in_array($p['id'],$packageIds)?'selected':'' ?>><?= esc($p['name']) ?></option><?php endforeach ?></select></label></div><div class="col-12"><h2 class="h5">FAQs</h2><?php for($i=0;$i<5;$i++): ?><div class="row g-2 mb-2"><div class="col-md-5"><input class="form-control" name="faq_question[]" placeholder="Question" value="<?= esc($faqs[$i]['question']??'','attr') ?>"></div><div class="col-md-7"><input class="form-control" name="faq_answer[]" placeholder="Answer" value="<?= esc($faqs[$i]['answer']??'','attr') ?>"></div></div><?php endfor ?></di